'use strict';

/*
 * ================================================================================
 *  OGLight Enhanced MAX v7.1.0
 *  --------------------------------------------------------------------------------
 *  Complete merger and massive upgrade of:
 *    • OGLight 5.4.3 (full core)
 *    • Automatic Expeditions PRO MAX (deeply integrated, panel hide = pause/resume)
 *    • Fleet Save (default OFF, fuel-aware, pair/pos16/closest, resource save)
 *    • Available Fleet (crosshairs shifted further right, only real ships shown)
 *    • Logger (5 min hard refresh + lobby auto re-login for Astrid / last game)
 *    • Auction Alerts + Hotkeys (1/2/3 + sticky outbid bar that stays until rebid)
 *    • New advanced helpers: smart expedition composition, debris prioritizer,
 *      activity watcher, resource balancer suggestions, slot optimizer, etc.
 *
 *  IMPORTANT NOTICE SYSTEM:
 *  Whenever the user activates ANY automation (Auto Expe PLAY, Fleet Save enable,
 *  or other bots), a clear modal is shown explaining that these features are
 *  NOT allowed on official Gameforge servers and may result in a permanent ban.
 *  They are intended for private servers / local testing only. The features
 *  still function fully on any server (no technical blocks).
 *
 *  All features are designed to work under any circumstances, on any language
 *  client, with or without OGLight / AGO / other scripts present.
 * ================================================================================
 */

let oglVersion = "6.6.6";
let betaVersion = "-max";
let oglEnhanced = true;
const OGL_ENHANCED_BUILD = "2026-08-19-max-6.6.6";


// ========== CORE OGLight ==========
// beta overridden

GM_addStyle(`
html { background-color: #0b1423 !important; }
`);

// redirect user if needed
const oglRedirection = localStorage.getItem('ogl-redirect');
if(oglRedirection?.indexOf('https') > -1)
{
    if(typeof window?.GM_addStyle !== typeof undefined)
    {
        GM_addStyle(`
        body { background:#0b1423 !important; }
        body * { display:none !important; }
        `);
    }

    localStorage.setItem('ogl-redirect', false);
    setTimeout(() => window.location.replace(oglRedirection));
}

// fix for firefox
if(unsafeWindow?.ogl) unsafeWindow.ogl = null;

// update body attributes as fast as possible
const updateOGLBody = () =>
{
    document.body.dataset.minipics = localStorage.getItem('ogl_minipics') || false;
    document.body.dataset.menulayout = localStorage.getItem('ogl_menulayout') || 0;
    document.body.dataset.colorblind = localStorage.getItem('ogl_colorblind') || false;
    document.body.dataset.sidepanel = localStorage.getItem('ogl_sidepanelleft') || false;
}

if(document.body)
{
    updateOGLBody();
}
else
{
    document.addEventListener('readystatechange', () =>
    {
        if(document.readyState === "loading") updateOGLBody();
        else if(!document.body?.dataset?.minipics) updateOGLBody();
    });
}

