// Helper block 000 – defensive coordinate & fleet utilities
Adv.advanced.helper_000 = function(input) {
    try {
        if (input == null) return null;
        if (typeof input === "string") {
            const m = input.match(/(\d+)[:\-](\d+)[:\-](\d+)/);
            if (m) return { galaxy: +m[1], system: +m[2], position: +m[3] };
        }
        if (typeof input === "object" && input.galaxy != null) {
            return { galaxy: +input.galaxy || 0, system: +input.system || 0, position: +input.position || 0 };
        }
        return null;
    } catch (e) {
        return null;
    }
};
Adv.advanced.validateShips_000 = function(ships) {
    if (!ships || typeof ships !== "object") return {};
    const out = {};
    Object.keys(ships).forEach(k => {
        const id = parseInt(k, 10);
        const qty = parseInt(ships[k], 10) || 0;
        if (id > 0 && qty > 0) out[id] = qty;
    });
        return out;
};


