// Additional theme CSS injected for dark/light consistency across all panels
const EXTRA_THEMES = `
/* Extra theme tokens for Enhanced MAX panels */
:root {
    --ogl-enhanced-accent: #38bdf8;
    --ogl-enhanced-danger: #ef4444;
    --ogl-enhanced-success: #22c55e;
    --ogl-enhanced-warn: #eab308;
    --ogl-enhanced-panel-bg: rgba(15,23,42,0.97);
    --ogl-enhanced-border: #334155;
}
body.ogl-enhanced-light {
    --ogl-enhanced-panel-bg: rgba(248,250,252,0.98);
    --ogl-enhanced-border: #cbd5e1;
}
/* Ensure Auto Expe and Fleet Save panels never go under OGLight side panels */
#autoExpoControlPanel, #ofc-panel {
max-height: 92vh;
overflow: hidden;
}
#autoExpoControlPanel .ae-log, #ofc-panel .ofc-history {
scrollbar-width: thin;
scrollbar-color: #475569 transparent;
}
`;
function injectExtraThemes() {
    if (document.getElementById("ogl-enhanced-extra-themes")) return;
    const s = document.createElement("style");
    s.id = "ogl-enhanced-extra-themes";
    s.textContent = EXTRA_THEMES;
    (document.head || document.documentElement).appendChild(s);
}
if (document.head) injectExtraThemes();
else document.addEventListener("DOMContentLoaded", injectExtraThemes);

// Final large documentation string (kept in memory for runtime help)
Adv.advanced.HELP = `
OGLight Enhanced MAX – Quick Reference
=====================================
• Auto Expeditions panel: PLAY starts (with warning), PAUSE, PREVIOUS step, RESET.
Hide panel with Ctrl+Alt+# → bot pauses. Show again → resumes if was active.
• Fleet Save: OFF by default. Enable via OGLightEnhanced.enableFleetSave(true)
or the unified settings. Always shows ban warning on first enable.
• Available Fleet: purple crosshairs on the right side of planets/moons that
actually have ships. Hover for grid. Only real ships (qty > 0) are listed.
• Auction: keys 1/2/3 select max metal/crystal/deut, Enter or R bids.
Outbid → sticky red bar at bottom that stays until you rebid.
• Logger: hard refresh every 5 minutes + automatic lobby "Dernière partie" /
Astrid click when detected.
• All automation that sends fleets shows the official-server warning modal.
Features still work on any server; the warning is informational only.
`;

